CREATE TABLE IF NOT EXISTS app_platform(app_id TEXT PRIMARY KEY REFERENCES apps(id), classification TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, revision INTEGER NOT NULL DEFAULT 1, active_submission TEXT);
CREATE TABLE IF NOT EXISTS capability_grants(app_id TEXT NOT NULL REFERENCES apps(id), subject TEXT NOT NULL, permission TEXT NOT NULL, PRIMARY KEY(app_id,subject,permission));
CREATE TABLE IF NOT EXISTS submissions(id TEXT PRIMARY KEY, app_id TEXT NOT NULL REFERENCES apps(id), version TEXT NOT NULL, manifest TEXT NOT NULL, manifest_digest TEXT NOT NULL, source_digest TEXT NOT NULL, source_blob BLOB NOT NULL, source_index TEXT NOT NULL, status TEXT NOT NULL, image TEXT, evidence TEXT, submitter TEXT NOT NULL, reviewer TEXT, created REAL NOT NULL, UNIQUE(app_id,version));
CREATE TABLE IF NOT EXISTS runtime_packages(ecosystem TEXT NOT NULL, name TEXT NOT NULL, version TEXT NOT NULL, integrity TEXT NOT NULL, source TEXT NOT NULL, approved INTEGER NOT NULL, PRIMARY KEY(ecosystem,name,version,integrity));
CREATE TABLE IF NOT EXISTS app_agents(app_id TEXT PRIMARY KEY REFERENCES apps(id), id TEXT NOT NULL UNIQUE, context_submission TEXT, created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS agent_changes(id TEXT PRIMARY KEY, app_id TEXT NOT NULL REFERENCES apps(id), submission_id TEXT NOT NULL REFERENCES submissions(id), requester TEXT NOT NULL, prompt TEXT NOT NULL, component TEXT NOT NULL, status TEXT NOT NULL, proposal TEXT, candidate_submission TEXT, created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS deployments(id TEXT PRIMARY KEY, app_id TEXT NOT NULL REFERENCES apps(id), submission_id TEXT NOT NULL REFERENCES submissions(id), environment TEXT NOT NULL, status TEXT NOT NULL, requested_by TEXT NOT NULL, expected_revision INTEGER NOT NULL, url TEXT, detail TEXT, created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS platform_jobs(id TEXT PRIMARY KEY, kind TEXT NOT NULL, target TEXT NOT NULL, status TEXT NOT NULL, lease_hash TEXT, lease_until REAL, attempts INTEGER NOT NULL DEFAULT 0, detail TEXT, created REAL NOT NULL);
CREATE INDEX IF NOT EXISTS idx_platform_jobs ON platform_jobs(kind,status,created);
CREATE TABLE IF NOT EXISTS runtime_sessions(hash TEXT PRIMARY KEY, session_hash TEXT NOT NULL REFERENCES sessions(hash) ON DELETE CASCADE, app_id TEXT NOT NULL REFERENCES apps(id), submission_id TEXT NOT NULL REFERENCES submissions(id), expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS audit_outbox(id TEXT PRIMARY KEY, payload TEXT NOT NULL, created REAL NOT NULL, delivered REAL);
CREATE TABLE IF NOT EXISTS data_products(source TEXT PRIMARY KEY, revision INTEGER NOT NULL, payload TEXT NOT NULL, digest TEXT NOT NULL, enabled INTEGER NOT NULL, updated REAL NOT NULL);
CREATE TABLE IF NOT EXISTS data_observations(source TEXT PRIMARY KEY REFERENCES data_products(source), product_digest TEXT NOT NULL, payload TEXT NOT NULL, observed REAL NOT NULL, expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS query_windows(user_id TEXT NOT NULL, window_start INTEGER NOT NULL, requests INTEGER NOT NULL, PRIMARY KEY(user_id,window_start));
